package org.brazilsoccer.mcp;
import java.lang.reflect.RecordComponent;
import java.util.*;

/** Deliberately small JSON parser/writer for JSON-RPC request/response envelopes. */
final class Json {
 static Object parse(String text){return new Parser(text).value();}
 static String write(Object o){if(o==null)return"null";if(o instanceof String s)return '"'+escape(s)+'"';if(o instanceof Number||o instanceof Boolean)return o.toString();if(o instanceof Match m){Map<String,Object>x=new LinkedHashMap<>();x.put("competition",m.competition());x.put("date",m.date()==null?null:m.date().toString());x.put("home",m.home());x.put("away",m.away());x.put("homeGoals",m.homeGoals());x.put("awayGoals",m.awayGoals());x.put("season",m.season());x.put("round",m.round());x.put("stage",m.stage());return write(x);}if(o instanceof Map<?,?>m){StringJoiner j=new StringJoiner(",","{","}");for(var e:m.entrySet())j.add(write(String.valueOf(e.getKey()))+":"+write(e.getValue()));return j.toString();}if(o instanceof Iterable<?> it){StringJoiner j=new StringJoiner(",","[","]");for(Object v:it)j.add(write(v));return j.toString();}return write(o.toString());}
 static String escape(String s){return s.replace("\\","\\\\").replace("\"","\\\"").replace("\n","\\n").replace("\r","\\r").replace("\t","\\t");}
 static final class Parser {final String s;int i;Parser(String s){this.s=s;}void ws(){while(i<s.length()&&Character.isWhitespace(s.charAt(i)))i++;}Object value(){ws();char c=s.charAt(i);if(c=='{')return obj();if(c=='[')return arr();if(c=='\"')return str();if(c=='t'){i+=4;return true;}if(c=='f'){i+=5;return false;}if(c=='n'){i+=4;return null;}int st=i;while(i<s.length()&&" ,]}\n\r\t".indexOf(s.charAt(i))<0)i++;String n=s.substring(st,i);return n.contains(".")?Double.valueOf(n):Long.valueOf(n);}Map<String,Object>obj(){Map<String,Object>m=new LinkedHashMap<>();i++;ws();if(s.charAt(i)=='}'){i++;return m;}while(true){ws();String k=str();ws();i++;Object v=value();m.put(k,v);ws();if(s.charAt(i)=='}'){i++;return m;}i++;}}List<Object>arr(){List<Object>a=new ArrayList<>();i++;ws();if(s.charAt(i)==']'){i++;return a;}while(true){a.add(value());ws();if(s.charAt(i)==']'){i++;return a;}i++;}}String str(){StringBuilder b=new StringBuilder();i++;while(i<s.length()){char c=s.charAt(i++);if(c=='\"')return b.toString();if(c=='\\'){char e=s.charAt(i++);b.append(switch(e){case 'n'->'\n';case 'r'->'\r';case 't'->'\t';case '"'->'"';case '\\'->'\\';default->e;});}else b.append(c);}throw new IllegalArgumentException("unterminated string");}}
}
